DELETE FROM errores_validacion WHERE origen_archivo IN ('Reporte_BUK_Novedades_Agosto2026.xlsx', 'Reporte_SIC_Ejecucion_2026.xlsx');
-- Importar/actualizar la ejecución real de SIC desde el staging de Excel. INSERT INTO errores_validacion (origen_archivo, persona_id, it, campo_error, valor_recibido, descripcion_error, severidad) SELECT 'Reporte_SIC_Ejecucion_2026.xlsx', s.PersonaId, s.IT, 'Datos SIC', s.Mes, 'Fila SIC descartada: profesional, instituto, mes o atenciones no son válidos.', 'ERROR_BLOQUEANTE' FROM stg_ejecucion_sic s WHERE TRY_CONVERT(INT, s.PersonaId) IS NULL OR TRY_CONVERT(INT, s.IT) IS NULL OR TRY_CONVERT(INT, s.Mes) IS NULL OR TRY_CONVERT(INT, s.Mes) NOT BETWEEN 1 AND 12 OR TRY_CONVERT(INT, s.Ate_Real_Directa) IS NULL OR TRY_CONVERT(INT, s.Ate_Real_Indirecta) IS NULL OR TRY_CONVERT(INT, s.Ate_Real_Total) IS NULL OR TRY_CONVERT(INT, s.Ate_Real_Directa) < 0 OR TRY_CONVERT(INT, s.Ate_Real_Indirecta) < 0 OR TRY_CONVERT(INT, s.Ate_Real_Total) < 0;
;WITH SIC AS ( SELECT TRY_CONVERT(INT, s.PersonaId) AS persona_id, TRY_CONVERT(INT, s.IT) AS it, TRIM(COALESCE(s.Instituto, '')) AS instituto, TRIM(COALESCE(s.Area, '')) AS area, TRY_CONVERT(INT, s.Mes) AS mes, TRY_CONVERT(INT, s.Ate_Real_Directa) AS ate_real_directa, TRY_CONVERT(INT, s.Ate_Real_Indirecta) AS ate_real_indirecta, TRY_CONVERT(INT, s.Ate_Real_Total) AS ate_real_total, TRY_CONVERT(FLOAT, s.Pct_Cumplimiento_Meta) AS pct_fuente FROM stg_ejecucion_sic s WHERE TRY_CONVERT(INT, s.PersonaId) IS NOT NULL AND TRY_CONVERT(INT, s.IT) IS NOT NULL AND TRY_CONVERT(INT, s.Mes) BETWEEN 1 AND 12 AND TRY_CONVERT(INT, s.Ate_Real_Directa) >= 0 AND TRY_CONVERT(INT, s.Ate_Real_Indirecta) >= 0 AND TRY_CONVERT(INT, s.Ate_Real_Total) >= 0 ), SIC_CON_META AS ( SELECT s.*, CASE WHEN p.meta_90_total > 0 THEN s.ate_real_total * 100.0 / p.meta_90_total ELSE COALESCE(s.pct_fuente, 0.0) END AS pct_cumplimiento_meta FROM SIC s LEFT JOIN planificacion_mensual p ON p.persona_id = s.persona_id AND p.it = s.it AND p.mes = s.mes ) MERGE dbo.ejecucion_sic AS destino USING SIC_CON_META AS fuente ON destino.persona_id = fuente.persona_id AND destino.it = fuente.it AND destino.mes = fuente.mes WHEN MATCHED THEN UPDATE SET destino.instituto = fuente.instituto, destino.area = fuente.area, destino.ate_real_directa = fuente.ate_real_directa, destino.ate_real_indirecta = fuente.ate_real_indirecta, destino.ate_real_total = fuente.ate_real_total, destino.pct_cumplimiento_meta = fuente.pct_cumplimiento_meta, destino.estado_alerta = CASE WHEN fuente.pct_cumplimiento_meta >= 100 THEN 'CUMPLIMIENTO_OPTIMO' WHEN fuente.pct_cumplimiento_meta >= 90 THEN 'EN_RIESGO' ELSE 'BAJO_META_90' END, destino.fecha_carga = CURRENT_TIMESTAMP WHEN NOT MATCHED THEN INSERT ( persona_id, it, instituto, area, mes, ate_real_directa, ate_real_indirecta, ate_real_total, pct_cumplimiento_meta, estado_alerta ) VALUES ( fuente.persona_id, fuente.it, fuente.instituto, fuente.area, fuente.mes, fuente.ate_real_directa, fuente.ate_real_indirecta, fuente.ate_real_total, fuente.pct_cumplimiento_meta, CASE WHEN fuente.pct_cumplimiento_meta >= 100 THEN 'CUMPLIMIENTO_OPTIMO' WHEN fuente.pct_cumplimiento_meta >= 90 THEN 'EN_RIESGO' ELSE 'BAJO_META_90' END );
-- 1. Detectar y registrar errores bloqueantes del archivo de novedades BUK INSERT INTO errores_validacion (origen_archivo, persona_id, it, cargo, campo_error, valor_recibido, descripcion_error, severidad) SELECT 'Reporte_BUK_Novedades_Agosto2026.xlsx', PersonaId, IT, Cargo, 'Horas Semanales', "Horas Semanales", CONCAT('ERROR: Jornada de ', "Horas Semanales", ' H/S excede el máximo legal permitido (44 H/S). Registro rechazado.'), 'ERROR_BLOQUEANTE' FROM stg_novedades_buk WHERE COALESCE(TRY_CONVERT(FLOAT, "Horas Semanales"), 0) > 44 OR COALESCE(TRY_CONVERT(FLOAT, "Horas Semanales"), 0) < 0;
INSERT INTO errores_validacion (origen_archivo, persona_id, it, cargo, campo_error, valor_recibido, descripcion_error, severidad) SELECT 'Reporte_BUK_Novedades_Agosto2026.xlsx', s.PersonaId, s.IT, s.Cargo, 'Cargo', s.Cargo, CONCAT('ERROR: El cargo "', s.Cargo, '" no existe en la matriz parametrizable Distribucion_NAC. Registro rechazado.'), 'ERROR_BLOQUEANTE' FROM stg_novedades_buk s LEFT JOIN distribucion_nac d ON TRIM(UPPER(s.Cargo)) = TRIM(UPPER(d.cargo)) WHERE d.cargo IS NULL AND TRIM(COALESCE(s.Cargo, '')) <> '';
-- 2. Detectar ALTAS NUEVAS válidas y registrarlas en auditoria_cambios y dotacion_asistencial INSERT INTO auditoria_cambios ( version_id, actor, tipo_evento, it, instituto, persona_id, entidad_afectada, campo_modificado, valor_anterior, valor_nuevo, mes_inicio_vigencia, impacto_atenciones_anual, justificacion, estado_aprobacion ) SELECT 2, 'Bot Blue Prism (03_Novedades_BUK_y_Contraste_SIC)', 'ALTA_PROFESIONAL', TRY_CONVERT(INT, s.IT), TRIM(s.Instituto), TRY_CONVERT(INT, s.PersonaId), CONCAT(TRIM(s.Cargo), ' (', TRIM(s.Instituto), ')'), 'Horas Semanales (Ago-Dic)', '0 H/S (Nuevo Ingreso)', CONCAT(s."Horas Semanales", ' H/S'), 8, CAST(ROUND(CAST(s."Horas Semanales" AS FLOAT) * 0.65 * 60.0 / d.std_min_directa * 21.0 * 0.90, 0) AS INT), 'Alta automática detectada en reporte BUK Agosto 2026 (Vigente desde 01-08-2026)', 'APROBADO' FROM stg_novedades_buk s INNER JOIN distribucion_nac d ON TRIM(UPPER(s.Cargo)) = TRIM(UPPER(d.cargo)) LEFT JOIN dotacion_asistencial da ON TRY_CONVERT(INT, s.PersonaId) = da.persona_id AND TRY_CONVERT(INT, s.IT) = da.it WHERE da.persona_id IS NULL AND CAST(s."Horas Semanales" AS FLOAT) > 0 AND CAST(s."Horas Semanales" AS FLOAT) <= 44;
-- Insertar las altas nuevas en dotacion_asistencial (vigentes ago..dic, 5 meses = 21 semanas calendario) INSERT INTO dotacion_asistencial ( orden, it, instituto, division, vacante_nuevo, fecha_inicio_contrato, horario_vigente, fecha_nacimiento, persona_id, cargo, area, ccosto, desc_ccosto, tipo_contrato, tipo_cargo, periodo_inicio_jornada, periodo_fin_jornada, hs_m8, hs_m9, hs_m10, hs_m11, hs_m12, vigencia_hs_12, hs_dic, prom_pond_hs, tramo_jornada, cambio_jornada, dias_semana_contrato, hd_promedio, colacion_en_contrato, horas_colacion_contrato, hs_disp_antes_nas_dic, hs_pausa_saludable, hs_nas_total, pct_nas_base, pct_directo_base, pct_indirecto_base, pct_nas_final_p2, pct_directo_final_p2, pct_indirecto_final_p2, pct_asistencial_p2, hs_disp_ate_p2, std_min_directa, std_min_indirecta, ate_dir_sem_p2, ate_ind_sem_p2, ate_dir_grupal_sem_p2, ate_ind_total_sem_p2, total_ate_sem_p2, cal_m8, cal_m9, cal_m10, cal_m11, cal_m12, semanas_habiles_planificadas, semhab_m8, semhab_m9, semhab_m10, semhab_m11, semhab_m12, semanas_habiles_totales, dias_habiles_totales, plan_anual_directa, plan_anual_indirecta, plan_anual_total, mg_anual_directa, mg_anual_indirecta, mg_anual_total, foja_pct, observaciones, version_id ) SELECT (SELECT COALESCE(MAX(orden), 471) + 1 FROM dotacion_asistencial), TRY_CONVERT(INT, s.IT), TRIM(s.Instituto), TRIM(s."Área"), 'Nuevo', '2026-08-01', '2026-12-31', '1994-06-15', TRY_CONVERT(INT, s.PersonaId), TRIM(s.Cargo), TRIM(s.Cod_Esp), CAST(s."Centro de Costo" AS INT), TRIM(s."Nombre Sub-área"), TRIM(s."Tipo de Contrato"), TRIM(s.Tipo_Trabajador), '2026-08-01', '2026-12-31', CAST(s."Horas Semanales" AS FLOAT), CAST(s."Horas Semanales" AS FLOAT), CAST(s."Horas Semanales" AS FLOAT), CAST(s."Horas Semanales" AS FLOAT), CAST(s."Horas Semanales" AS FLOAT), 1, CAST(s."Horas Semanales" AS FLOAT), CAST(s."Horas Semanales" AS FLOAT), CASE WHEN CAST(s."Horas Semanales" AS FLOAT) >= 40 THEN '>=40' ELSE '22-40' END, 'Aumento', CAST(s.Ndias AS FLOAT), ROUND(CAST(s."Horas Semanales" AS FLOAT) / CAST(s.Ndias AS FLOAT), 1), 'N', 0, CAST(s."Horas Semanales" AS FLOAT), ROUND(CAST(s."Horas Semanales" AS FLOAT) * 0.10, 2), ROUND(CAST(s."Horas Semanales" AS FLOAT) * d.t1_pct_nas, 2), d.t1_pct_nas, d.t1_pct_dir, d.t1_pct_ind, d.t1_pct_nas, d.t1_pct_dir, d.t1_pct_ind, (1.0 - d.t1_pct_nas), CAST(s."Horas Semanales" AS FLOAT) * (1.0 - d.t1_pct_nas), d.std_min_directa, d.std_min_indirecta, CAST(CAST(s."Horas Semanales" AS FLOAT) * d.t1_pct_dir * 60.0 / d.std_min_directa AS INT), CAST(CAST(s."Horas Semanales" AS FLOAT) * d.t1_pct_ind * 60.0 / d.std_min_indirecta AS INT), CAST(CAST(s."Horas Semanales" AS FLOAT) * d.t1_pct_dir * 60.0 / d.std_min_directa AS INT), CAST(CAST(s."Horas Semanales" AS FLOAT) * d.t1_pct_ind * 60.0 / d.std_min_indirecta AS INT), CAST(CAST(s."Horas Semanales" AS FLOAT) * d.t1_pct_dir * 60.0 / d.std_min_directa AS INT) + CAST(CAST(s."Horas Semanales" AS FLOAT) * d.t1_pct_ind * 60.0 / d.std_min_indirecta AS INT), 4.2, 4.2, 4.2, 4.2, 4.2, 21.0, 4.0, 4.0, 4.0, 4.0, 4.0, 20.0, 100.0, 20 * CAST(CAST(s."Horas Semanales" AS FLOAT) * d.t1_pct_dir * 60.0 / d.std_min_directa AS INT), 20 * CAST(CAST(s."Horas Semanales" AS FLOAT) * d.t1_pct_ind * 60.0 / d.std_min_indirecta AS INT), 20 * (CAST(CAST(s."Horas Semanales" AS FLOAT) * d.t1_pct_dir * 60.0 / d.std_min_directa AS INT) + CAST(CAST(s."Horas Semanales" AS FLOAT) * d.t1_pct_ind * 60.0 / d.std_min_indirecta AS INT)), CAST(20 * CAST(CAST(s."Horas Semanales" AS FLOAT) * d.t1_pct_dir * 60.0 / d.std_min_directa AS INT) * 0.90 AS INT), CAST(20 * CAST(CAST(s."Horas Semanales" AS FLOAT) * d.t1_pct_ind * 60.0 / d.std_min_indirecta AS INT) * 0.90 AS INT), CAST(20 * (CAST(CAST(s."Horas Semanales" AS FLOAT) * d.t1_pct_dir * 60.0 / d.std_min_directa AS INT) + CAST(CAST(s."Horas Semanales" AS FLOAT) * d.t1_pct_ind * 60.0 / d.std_min_indirecta AS INT)) * 0.90 AS INT), ROUND(d.t1_pct_dir * 100.0, 2), 'Alta incorporada automáticamente por Blue Prism (Agosto 2026)', 2 FROM stg_novedades_buk s INNER JOIN distribucion_nac d ON TRIM(UPPER(s.Cargo)) = TRIM(UPPER(d.cargo)) LEFT JOIN dotacion_asistencial da ON TRY_CONVERT(INT, s.PersonaId) = da.persona_id AND TRY_CONVERT(INT, s.IT) = da.it WHERE da.persona_id IS NULL AND CAST(s."Horas Semanales" AS FLOAT) > 0 AND CAST(s."Horas Semanales" AS FLOAT) <= 44;
-- 3. Detectar CAMBIOS DE JORNADA y BAJAS en profesionales existentes y auditarlos INSERT INTO auditoria_cambios ( version_id, actor, tipo_evento, it, instituto, persona_id, entidad_afectada, campo_modificado, valor_anterior, valor_nuevo, mes_inicio_vigencia, impacto_atenciones_anual, justificacion, estado_aprobacion ) SELECT 2, 'Bot Blue Prism (03_Novedades_BUK_y_Contraste_SIC)', CASE WHEN CAST(s."Horas Semanales" AS FLOAT) = 0 THEN 'BAJA_TERMINO_CONTRATO' WHEN CAST(s."Horas Semanales" AS FLOAT) > da.hs_dic THEN 'CAMBIO_JORNADA_AUMENTO' ELSE 'CAMBIO_JORNADA_DISMINUCION' END, da.it, da.instituto, da.persona_id, CONCAT(da.cargo, ' (PersonaId ', CONVERT(NVARCHAR(30), da.persona_id), ')'), 'Horas Semanales (Ago-Dic)', CONCAT(CONVERT(NVARCHAR(30), CAST(da.hs_dic AS INT)), ' H/S'), CONCAT(CONVERT(NVARCHAR(30), TRY_CONVERT(INT, s."Horas Semanales")), ' H/S'), 8, CAST(ROUND((CAST(s."Horas Semanales" AS FLOAT) - da.hs_dic) / CASE WHEN da.hs_dic > 0 THEN da.hs_dic ELSE 1 END * (da.mg_tot_m8 + da.mg_tot_m9 + da.mg_tot_m10 + da.mg_tot_m11 + da.mg_tot_m12), 0) AS INT), 'Ajuste automático de planificación desde Agosto 2026 por cambio en reporte BUK', 'APROBADO' FROM stg_novedades_buk s INNER JOIN distribucion_nac d ON TRIM(UPPER(s.Cargo)) = TRIM(UPPER(d.cargo)) INNER JOIN dotacion_asistencial da ON TRY_CONVERT(INT, s.PersonaId) = da.persona_id AND TRY_CONVERT(INT, s.IT) = da.it WHERE CAST(s."Horas Semanales" AS FLOAT) >= 0 AND CAST(s."Horas Semanales" AS FLOAT) <= 44 AND CAST(s."Horas Semanales" AS FLOAT) <> da.hs_dic;
-- 4. Ajustar planificación en dotacion_asistencial desde el mes 8 (Agosto a Diciembre) proporcionalmente UPDATE dotacion_asistencial SET cambio_jornada = CASE WHEN (SELECT CAST(s."Horas Semanales" AS FLOAT) FROM stg_novedades_buk s WHERE TRY_CONVERT(INT, s.PersonaId) = dotacion_asistencial.persona_id AND TRY_CONVERT(INT, s.IT) = dotacion_asistencial.it) > hs_dic THEN 'Aumento' ELSE 'Disminución' END, plan_anual_directa = (plan_dir_m1 + plan_dir_m2 + plan_dir_m3 + plan_dir_m4 + plan_dir_m5 + plan_dir_m6 + plan_dir_m7) + ROUND((plan_dir_m8 + plan_dir_m9 + plan_dir_m10 + plan_dir_m11 + plan_dir_m12) * ((SELECT CAST(s."Horas Semanales" AS FLOAT) FROM stg_novedades_buk s WHERE TRY_CONVERT(INT, s.PersonaId) = dotacion_asistencial.persona_id AND TRY_CONVERT(INT, s.IT) = dotacion_asistencial.it) / CASE WHEN hs_dic > 0 THEN hs_dic ELSE 1 END), 0), plan_anual_total = (plan_tot_m1 + plan_tot_m2 + plan_tot_m3 + plan_tot_m4 + plan_tot_m5 + plan_tot_m6 + plan_tot_m7) + ROUND((plan_tot_m8 + plan_tot_m9 + plan_tot_m10 + plan_tot_m11 + plan_tot_m12) * ((SELECT CAST(s."Horas Semanales" AS FLOAT) FROM stg_novedades_buk s WHERE TRY_CONVERT(INT, s.PersonaId) = dotacion_asistencial.persona_id AND TRY_CONVERT(INT, s.IT) = dotacion_asistencial.it) / CASE WHEN hs_dic > 0 THEN hs_dic ELSE 1 END), 0), mg_anual_directa = (mg_dir_m1 + mg_dir_m2 + mg_dir_m3 + mg_dir_m4 + mg_dir_m5 + mg_dir_m6 + mg_dir_m7) + ROUND((mg_dir_m8 + mg_dir_m9 + mg_dir_m10 + mg_dir_m11 + mg_dir_m12) * ((SELECT CAST(s."Horas Semanales" AS FLOAT) FROM stg_novedades_buk s WHERE TRY_CONVERT(INT, s.PersonaId) = dotacion_asistencial.persona_id AND TRY_CONVERT(INT, s.IT) = dotacion_asistencial.it) / CASE WHEN hs_dic > 0 THEN hs_dic ELSE 1 END), 0), mg_anual_total = (mg_tot_m1 + mg_tot_m2 + mg_tot_m3 + mg_tot_m4 + mg_tot_m5 + mg_tot_m6 + mg_tot_m7) + ROUND((mg_tot_m8 + mg_tot_m9 + mg_tot_m10 + mg_tot_m11 + mg_tot_m12) * ((SELECT CAST(s."Horas Semanales" AS FLOAT) FROM stg_novedades_buk s WHERE TRY_CONVERT(INT, s.PersonaId) = dotacion_asistencial.persona_id AND TRY_CONVERT(INT, s.IT) = dotacion_asistencial.it) / CASE WHEN hs_dic > 0 THEN hs_dic ELSE 1 END), 0), hs_dic = (SELECT CAST(s."Horas Semanales" AS FLOAT) FROM stg_novedades_buk s WHERE TRY_CONVERT(INT, s.PersonaId) = dotacion_asistencial.persona_id AND TRY_CONVERT(INT, s.IT) = dotacion_asistencial.it), vigencia_hs_12 = CASE WHEN (SELECT CAST(s."Horas Semanales" AS FLOAT) FROM stg_novedades_buk s WHERE TRY_CONVERT(INT, s.PersonaId) = dotacion_asistencial.persona_id AND TRY_CONVERT(INT, s.IT) = dotacion_asistencial.it) > 0 THEN 1 ELSE 0 END, observaciones = 'Actualizado por Bot Blue Prism (Novedades Agosto 2026)', version_id = 2, updated_at = CURRENT_TIMESTAMP WHERE EXISTS ( SELECT 1 FROM stg_novedades_buk s INNER JOIN distribucion_nac d ON TRIM(UPPER(s.Cargo)) = TRIM(UPPER(d.cargo)) WHERE TRY_CONVERT(INT, s.PersonaId) = dotacion_asistencial.persona_id AND TRY_CONVERT(INT, s.IT) = dotacion_asistencial.it AND CAST(s."Horas Semanales" AS FLOAT) >= 0 AND CAST(s."Horas Semanales" AS FLOAT) <= 44 AND CAST(s."Horas Semanales" AS FLOAT) <> dotacion_asistencial.hs_dic );
UPDATE dotacion_asistencial SET plan_anual_indirecta = plan_anual_total - plan_anual_directa, mg_anual_indirecta = mg_anual_total - mg_anual_directa WHERE version_id = 2;
